from __future__ import annotations

import pytest

from llm_router import Provider
from llm_router._internal.providers.base import ProviderCredential
from llm_router._internal.providers.registry import register_adapter_factory

pytestmark = pytest.mark.verification_kind("unit")


def _factory(*args: object, **kwargs: object) -> object:
    return (args, kwargs)


@pytest.mark.verifies("TREQ_GEMINI_WEBAPI_ADAPTER_BOUNDARY[revision==1]")
def test_gemini_webapi_factory_is_already_registered() -> None:
    assert ProviderCredential(key_id=1, env_var="GEMINI_WEBAPI_COOKIE", value="")
    with pytest.raises(Exception, match=r"(?i)gemini|already|regist|duplicate"):
        register_adapter_factory(Provider.GEMINI_WEBAPI, _factory)
